import { cn } from 'cn';
import { ChevronLeftIcon, RefreshCwIcon } from 'lucide-react';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useNavigate, useParams } from 'react-router';

import type { AskAnswerActions } from '@/components/agent';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from '@/components/ui/resizable';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';

import type {
  ActiveRunView,
  ArtifactEnvelope,
  ChangeDetail,
  ChangeRunEntry,
} from '../../types/dto';
import { ArchitecturePanel } from '../architecture/components/architecture-panel';
import { ChangeChatPanel } from './agent';
import {
  mountMaterials,
  ChangeFlowGraph,
  DetailDrawer,
  buildFlowGraph,
  RunControlPanel,
  runStepNodes,
  unifiedRunEdges,
  unifiedRunNodes,
  type DrawerSelection,
  type FlowGraph,
  type FlowMaterials,
} from './flow';
import { useChangeDetail } from './hooks/use-change-detail';
import { useChangeFlowRun } from './hooks/use-change-flow-run';

function formatTime(value: string | null): string {
  if (value === null) return '—';
  return value;
}

function ReturnButton({ onClick }: { onClick: () => void }): React.JSX.Element {
  return (
    <Button variant="ghost" size="icon" title="返回列表" onClick={onClick}>
      <ChevronLeftIcon />
    </Button>
  );
}

function DetailHeader({ detail, onBack }: { detail: ChangeDetail; onBack: () => void }) {
  return (
    <div className="mb-3" data-testid="detail-header">
      <div className="flex flex-wrap items-center gap-2.5">
        <ReturnButton onClick={onBack} />
        <h2 className="m-0 break-all text-[17px]">{detail.title}</h2>
        <span className="text-muted-foreground">
          {detail.source === 'archive' ? '已归档' : '进行中'}
        </span>
        {detail.created !== null && <span className="text-muted-foreground">{detail.created}</span>}
        {detail.activePhase !== null && (
          <Badge variant="secondary">
            运行中 · {detail.activePhase.phase} · attempt {detail.activePhase.attempt}
            {detail.activePhase.startAt !== null && ` · ${formatTime(detail.activePhase.startAt)}`}
          </Badge>
        )}
      </div>
      {detail.worktree !== null && (
        <div className="mt-1 break-all text-xs text-muted-foreground" data-testid="detail-worktree">
          worktree：{detail.worktree}
        </div>
      )}
      {detail.execRoot !== null && (
        <div
          className="mt-1 break-all text-xs text-muted-foreground"
          data-testid="detail-exec-root"
        >
          执行根：{detail.execRoot}
        </div>
      )}
    </div>
  );
}

/** 流程图 */
function FlowSection({
  graph,
  materials,
  onSelect,
  loading,
  onRefresh,
}: {
  graph: FlowGraph;
  materials: FlowMaterials;
  onSelect: (selection: DrawerSelection) => void;
  loading: boolean;
  onRefresh: () => void;
}): React.JSX.Element {
  return (
    <section className="h-full mb-4 rounded-lg border border-border bg-card px-4 py-3.5 flex flex-col">
      <div className="mb-2.5 flex items-center gap-1.5">
        <h2 className="m-0 text-[15px]">流程图</h2>
        <Button
          variant="outline"
          size="icon-sm"
          title="刷新详情"
          aria-label="刷新详情"
          disabled={loading}
          onClick={onRefresh}
          data-testid="refresh-change-detail-button"
        >
          <RefreshCwIcon className={cn({ 'animate-spin': loading })} />
        </Button>
      </div>
      <ChangeFlowGraph graph={graph} materials={materials} onSelect={onSelect} />
    </section>
  );
}

/** 详情降级页：错误 / 加载中 / 未找到共用，error 控制提示样式。 */
function DetailFallback({
  message,
  error = false,
  onBack,
}: {
  message: string;
  error?: boolean;
  onBack: () => void;
}) {
  return (
    <div>
      <ReturnButton onClick={onBack} />
      {error ? (
        <div
          className="mb-3 break-all rounded-md bg-fail-bg px-3 py-2 text-fail"
          data-testid="error-note"
        >
          {message}
        </div>
      ) : (
        <div className="text-muted-foreground" data-testid="detail-note">
          {message}
        </div>
      )}
    </div>
  );
}

/** 刷新失败 */
function RefreshStaleNote({ message }: { message: string }): React.JSX.Element {
  return (
    <div
      className="mb-3 break-all rounded-md bg-fail-bg px-3 py-2 text-[13px] text-fail"
      data-testid="refresh-stale-note"
    >
      {`刷新失败：${message}——页面显示的是最近一次成功结果，将自动重试；也可点击「刷新详情」立即重试。`}
    </div>
  );
}

/**
 * 根切换抑制（原 ChangeView 语义迁入）：workspace 根变更（select / 移除当前根 /
 * 添加新根）且详情仍带旧选中时，过渡轮以 null 抑制取数（防「新根 + 旧 id」误发
 * get_change_detail），effect 中 replace 导航回 /changes（URL 无 :id 段）；
 * 落点后详情页随路由卸载，抑制位无须显式清位（清位早于落点提交反而会留出
 * 「新根 + 旧 id」中间提交，重新武装误发）。返回参与取数的 change id。
 */
function useRootSwitchSuppress(root: string | null, id: string | null): string | null {
  const navigate = useNavigate();
  const [prevRoot, setPrevRoot] = useState(root);
  const [resetPending, setResetPending] = useState(false);

  // 渲染期调整（沿用既有模式）：根切换且带旧选中 → 置待导航标记
  if (prevRoot !== root) {
    setPrevRoot(root);
    if (id !== null) setResetPending(true);
  }

  useEffect(() => {
    if (resetPending) {
      void navigate('/changes', { replace: true }); // workspace 切换落清单，URL 无 :id 段
    }
  }, [resetPending, navigate]);

  return resetPending ? null : id;
}

/** 流程图 + 产物区 + 抽屉（selection 联动态自持：图节点点击开抽屉，开关不出
 * 本组件——卸载即复位，与降级页分流语义一致；页内单一身份源 = URL id）。 */
function DetailContent({
  root,
  id,
  name,
  graph,
  materials,
  sessionRefreshKey,
  askAnswer,
  refreshLoading,
  onRefresh,
}: {
  root: string | null;
  id: string;
  /** change name（stdout 面板磁盘面寻址键——与 record 同口径，非 id） */
  name: string;
  graph: FlowGraph;
  materials: FlowMaterials;
  sessionRefreshKey: number;
  askAnswer: AskAnswerActions;
  /** 手动刷新在飞（仅刷新按钮禁用面，主图面不回落加载占位） */
  refreshLoading: boolean;
  onRefresh: () => void;
}): React.JSX.Element {
  const [selection, setSelection] = useState<DrawerSelection | null>(null);
  return (
    <>
      <FlowSection
        graph={graph}
        materials={materials}
        onSelect={setSelection}
        loading={refreshLoading}
        onRefresh={onRefresh}
      />
      <DetailDrawer
        selection={selection}
        graph={graph}
        materials={materials}
        root={root}
        changeId={id}
        name={name}
        sessionRefreshKey={sessionRefreshKey}
        askAnswer={askAnswer}
        onClose={() => setSelection(null)}
      />
    </>
  );
}

function DetailTabs({
  detail,
  execRoot,
  refreshDetail,
  refreshLoading,
  root,
  id,
  graph,
  materials,
  sessionRefreshKey,
  askAnswer,
}: {
  detail: ChangeDetail;
  /** 执行根（`detail.execRoot ?? detail.worktree`；由详情体单点解析后下传） */
  execRoot: string | null;
  refreshDetail: () => void;
  refreshLoading: boolean;
  root: string | null;
  id: string;
  graph: FlowGraph;
  materials: FlowMaterials;
  sessionRefreshKey: number;
  askAnswer: AskAnswerActions;
}): React.JSX.Element {
  const archiRoot = detail.source === 'archive' || execRoot === null ? root : execRoot;
  return (
    <Tabs className="h-full min-h-0" defaultValue="flow">
      <TabsList data-testid="detail-tabs">
        <TabsTrigger data-testid="detail-tab-flow" value="flow">
          流程
        </TabsTrigger>
        <TabsTrigger data-testid="detail-tab-architecture" value="architecture">
          架构
        </TabsTrigger>
      </TabsList>
      <TabsContent className="min-h-0 flex-1" value="flow">
        <DetailContent
          root={root}
          id={id}
          name={detail.name}
          graph={graph}
          materials={materials}
          sessionRefreshKey={sessionRefreshKey}
          askAnswer={askAnswer}
          refreshLoading={refreshLoading}
          onRefresh={refreshDetail}
        />
      </TabsContent>
      <TabsContent className="min-h-0 flex-1" value="architecture">
        <ArchitecturePanel root={archiRoot} mode="incremental" />
      </TabsContent>
    </Tabs>
  );
}

interface DetailLoadedProps {
  detail: ChangeDetail;
  refreshDetail: () => void;
  refreshLoading: boolean;
  /** 在飞 run 活面（统一视图 activeRun） */
  activeRun: ActiveRunView | null;
  root: string | null;
  /** 页内单一身份源（URL id；name 恒展示面取自 detail.name） */
  id: string | null;
  artifacts: ArtifactEnvelope[];
  run: ReturnType<typeof useChangeFlowRun>;
  header: React.JSX.Element;
  /** 内联「刷新失败」错误串（null = 无陈旧窗口；非 null = 保 last-good 中） */
  staleError: string | null;
  sessionRefreshKey: number;
}

/** 页内动作面板组（运行控制面承载发起 / 停止 / 停等确认 / ask 应答——归档确认
 * 对话由 stop-before-archive 停等面承载；显名收敛：命令面取 URL id、展示面取
 * `detail.name`）。 */
function DetailActionPanels({
  detail,
  id,
  root,
  activeRun,
  lastRun,
  run,
}: {
  detail: ChangeDetail;
  id: string | null;
  /** 主仓根（归档确认面的架构变更区块据它开库取数） */
  root: string | null;
  activeRun: ActiveRunView | null;
  lastRun: ChangeRunEntry | null;
  run: ReturnType<typeof useChangeFlowRun>;
}): React.JSX.Element {
  return (
    <>
      {id !== null && (
        <RunControlPanel
          changeId={id}
          name={detail.name}
          root={root}
          activeRun={activeRun}
          lastRun={lastRun}
          actions={run}
        />
      )}
    </>
  );
}

/** 执行图数据源（拼缝单源化：步节点 = runs[].nodes ∪ activeRun.nodes、边 =
 * runs[].edges ∪ activeRun.edges 同一转换函数——图常驻渲染，回落分支退场）。 */
function useFlowGraphData(
  detail: ChangeDetail,
  activeRun: ActiveRunView | null,
  artifacts: ArtifactEnvelope[],
): { graph: FlowGraph; materials: FlowMaterials; lastRun: ChangeRunEntry | null } {
  // 列序单源 = `detail.pipeline` 出线序（requirement 9 列 / test-only 6 列）
  const phaseOrder = useMemo(() => detail.pipeline.map((entry) => entry.phase), [detail]);
  const runNodes = useMemo(
    () => runStepNodes(unifiedRunNodes(detail.runs, activeRun), phaseOrder),
    [detail.runs, activeRun, phaseOrder],
  );
  const runEdges = useMemo(() => unifiedRunEdges(detail.runs, activeRun), [detail.runs, activeRun]);
  const graph = useMemo<FlowGraph>(
    () => buildFlowGraph(detail, runNodes, runEdges),
    [detail, runNodes, runEdges],
  );
  const materials = useMemo<FlowMaterials>(
    () => mountMaterials(detail, artifacts),
    [detail, artifacts],
  );
  const lastRun = detail.runs.length > 0 ? detail.runs[detail.runs.length - 1] : null;
  return { graph, materials, lastRun };
}

/** 详情已载入形态 */
function DetailLoaded({
  detail,
  refreshDetail,
  refreshLoading,
  activeRun,
  root,
  id,
  artifacts,
  run,
  header,
  staleError,
  sessionRefreshKey,
}: DetailLoadedProps): React.JSX.Element {
  const { graph, materials, lastRun } = useFlowGraphData(detail, activeRun, artifacts);
  // 执行根派生单点：`execRoot` 是记录原始列（根 workspace / legacy 为 null），
  // 路径消费面一律回落 `worktree`——画布根与会话 cwd 共用本值
  const execRoot = detail.execRoot ?? detail.worktree;
  // 流程侧 ask 动作面：走 `run.answer` 使 `Err` 落 `run.error` 既有错误行（与裸调
  // `changeFlowAnswer` 参数面逐字等价）；活卡判据 = 当前等待条目的 `toolCallId`
  const askAnswer = useMemo<AskAnswerActions>(
    () => ({
      onAnswer: (text: string) => {
        void run.answer(text);
      },
      pendingToolCallId: activeRun?.ask?.toolCallId ?? null,
    }),
    [run.answer, activeRun?.ask?.toolCallId],
  );
  return (
    <div className="flex flex-col h-full">
      {header}
      <ResizablePanelGroup className="min-h-0 flex-1" orientation="horizontal">
        <ChangeChatPanel
          root={root}
          changeId={id ?? detail.id}
          cwd={execRoot}
          readOnly={detail.source === 'archive'}
          runActive={activeRun !== null}
        />
        <ResizableHandle withHandle />
        <ResizablePanel minSize="20">
          <div className="flex h-full min-h-0 flex-col pl-1.5">
            {staleError !== null && <RefreshStaleNote message={staleError} />}
            <DetailActionPanels
              detail={detail}
              id={id}
              root={root}
              activeRun={activeRun}
              lastRun={lastRun}
              run={run}
            />
            <div className="flex-1 min-h-0">
              <DetailTabs
                detail={detail}
                execRoot={execRoot}
                refreshDetail={refreshDetail}
                refreshLoading={refreshLoading}
                root={root}
                id={id ?? detail.id}
                graph={graph}
                materials={materials}
                sessionRefreshKey={sessionRefreshKey}
                askAnswer={askAnswer}
              />
            </div>
          </div>
        </ResizablePanel>
      </ResizablePanelGroup>
    </div>
  );
}

/**
 * change 详情视图
 */
/** 显式返回清单（不用历史回退——既有语义）。 */
function useBackToList(): () => void {
  const navigate = useNavigate();
  return useCallback(() => navigate('/changes'), [navigate]);
}

/** 详情页数据面（取数 + 通知归一 + run 控制；参数 id 化）——视图组件薄装配
 *（max-lines 纪律；通知不分流：会话事件与其余同走统一重查 tick）。归档面已
 * 并入 run 流程（archive 相位 + stop-before-archive 停等面），无独立归档链
 * 状态源）。 */
function useDetailViewData(root: string | null, id: string | null) {
  const {
    detail,
    activeRun,
    artifacts,
    loading,
    error,
    refreshFailed,
    refresh,
    notifyRefresh,
    refreshTick,
  } = useChangeDetail(root, id);
  // 通知不分流（D8）：会话事件（SessionEvent）与其余 kind 同走统一视图重查
  // （300ms 去抖）——通知仅失效 / 状态重评估信号、查询结果权威；实时面走会话
  // 订阅（delta 不落库，重查只能见密封粒度）
  const onNotice = useCallback(() => {
    notifyRefresh();
  }, [notifyRefresh]);
  const run = useChangeFlowRun({
    root,
    id,
    activeRunPresent: activeRun !== null,
    onNotice,
  });
  return {
    detail,
    activeRun,
    artifacts,
    loading,
    error,
    refreshFailed,
    refresh,
    run,
    refreshTick,
  };
}

export function ChangeDetailView({ root }: { root: string | null }) {
  const params = useParams<'id'>();
  const id = useRootSwitchSuppress(root, params.id ?? null);
  const { detail, activeRun, artifacts, loading, error, refreshFailed, refresh, run, refreshTick } =
    useDetailViewData(root, id);
  const backToList = useBackToList();

  // error 已收敛为首载语义（detail 在手的刷新失败落 refreshFailed 走内联横
  // 幅，不再触整页 DetailFallback）——本分支只承接首载失败（无可保）
  if (error !== null) {
    return <DetailFallback message={`详情加载失败：${error}`} error onBack={backToList} />;
  }
  if (loading && detail === null) {
    return <DetailFallback message="加载中…" onBack={backToList} />;
  }
  if (detail === null) {
    return <DetailFallback message="未找到该 change。" onBack={backToList} />;
  }
  return (
    <DetailLoaded
      detail={detail}
      refreshDetail={refresh}
      refreshLoading={loading}
      activeRun={activeRun}
      root={root}
      id={id}
      artifacts={artifacts}
      run={run}
      staleError={refreshFailed}
      header={<DetailHeader detail={detail} onBack={backToList} />}
      sessionRefreshKey={refreshTick}
    />
  );
}

