    expect(screen.getByTestId('flow-graph')).toBeTruthy();

    // 半边二：首载失败（detail 不在手）→ 整页错误兜底页（既有语义不变）
    planDetailRounds([{ kind: 'reject', message: 'IPC 断开' }]);
